INSERT INTO `wp_posts` VALUES (1,1,'2025-07-22 08:47:44','2025-07-22 06:47:44','<!-- wp:paragraph -->\n<p>Witamy w WordPressie. To jest twój pierwszy wpis. Edytuj go lub usuń, a następnie zacznij pisać!</p>\n<!-- /wp:paragraph -->','Witaj, świecie!','','trash','open','open','','witaj-swiecie__trashed','','','2025-09-25 17:18:51','2025-09-25 15:18:51','',0,'http://localhost/bedrock/web/?p=1',0,'post','',1),(361,1,'2025-10-11 14:02:10','2025-10-11 12:02:10','<!-- wp:group {\"metadata\":{\"name\":\"Navigation\"},\"className\":\"navigation\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group navigation\"><!-- wp:group {\"tagName\":\"header\",\"metadata\":{\"name\":\"Header\"},\"className\":\"navigation-header\",\"layout\":{\"type\":\"constrained\"}} -->\n<header class=\"wp-block-group navigation-header\"><!-- wp:site-logo {\"shouldSyncIcon\":true} /-->\n\n<!-- wp:html -->\n<button class=\"menu-toggle\" aria-controls=\"main-menu\" aria-expanded=\"false\">\n    Menu\n  </button>\n<!-- /wp:html --></header>\n<!-- /wp:group -->\n\n<!-- wp:navigation {\"ref\":35,\"overlayMenu\":\"never\",\"className\":\"navigation-panel\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} /--></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"main\",\"metadata\":{\"name\":\"Content\"},\"className\":\"main-content\",\"backgroundColor\":\"white\",\"layout\":{\"type\":\"default\"}} -->\n<main class=\"wp-block-group main-content has-white-background-color has-background\"><!-- wp:post-content {\"align\":\"wide\"} /--></main>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"footer\",\"metadata\":{\"name\":\"Footer\"},\"className\":\"footer\",\"backgroundColor\":\"black\",\"layout\":{\"type\":\"default\"}} -->\n<footer class=\"wp-block-group footer has-black-background-color has-background\"><!-- wp:group {\"className\":\"wrapper footer-wrapper\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group wrapper footer-wrapper\"><!-- wp:group {\"className\