tton.setAttribute(\'aria-expanded\', !expanded);\n\n      if (!expanded) {\n        // ustaw maxHeight na wysokość zawartości\n        target.style.maxHeight = target.scrollHeight + \"px\";\n      } else {\n        // ustaw maxHeight na 0 (zwinięcie)\n        target.style.maxHeight = \"0px\";\n      }\n    });\n  });\n</script>\n\n<!-- /wp:html --></div>\n<!-- /wp:group --></section>\n<!-- /wp:group -->','Strona Główna','','inherit','closed','closed','','54-revision-v1','','','2025-09-23 17:58:23','2025-09-23 15:58:23','',54,'http://localhost/bedrock/web/?p=241',0,'revision','',0),(239,2,'2025-09-23 17:55:01','2025-09-23 15:55:01','<!-- wp:group {\"tagName\":\"section\",\"metadata\":{\"categories\":[\"custom/custom-patterns\"],\"patternName\":\"custom/video-noise\",\"name\":\"Video Noise Hero\"},\"className\":\"video-noise-hero \",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group video-noise-hero\"><!-- wp:video {\"id\":69,\"className\":\"hero-video\"} -->\n<figure class=\"wp-block-video hero-video\"><video autoplay loop muted src=\"http://localhost/bedrock/web/app/uploads/2025/09/fQM1RaSPcHPbMZR0PCsoGur0U.mp4\" playsinline></video></figure>\n<!-- /wp:video -->\n\n<!-- wp:image {\"id\":78,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"align\":\"center\",\"className\":\"hero-logo\"} -->\n<figure class=\"wp-block-image aligncenter size-large hero-logo\"><img src=\"http://localhost/bedrock/web/app/uploads/2025/09/logo-scrren.svg\" alt=\"\" class=\"wp-image-78\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"className\":\"hero-noise\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"wp-block-group hero-noise\"></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"hero-content\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group hero-content\"><!-- wp:list {\"className\":\"hero-services\"} -->\n<ul class=\"wp-block-list hero-services\"><!-- wp:list-item {\"style\":{\"elements\":{\"link